def _get_default_gpu_device_type() -> str:
    avail_gpus = [
        device_type
        for device_type in GPU_BENCHMARK_DEVICE_TYPES
        if getattr(torch, device_type).is_available()
    ]
    assert len(avail_gpus) <= 1
    return "cuda" if len(avail_gpus) == 0 else avail_gpus.pop()

def _normalize_gpu_device_type(device_type: str | torch.device | None) -> str:
    if device_type is None:
        return _get_default_gpu_device_type()
    if isinstance(device_type, torch.device):
        return device_type.type
    return torch.device(device_type).type

def nonzero(fake_mode: FakeTensorMode, func: OpOverload, arg: FakeTensor) -> FakeTensor:
    if (
        fake_mode.shape_env is None
        or not fake_mode.shape_env.allow_dynamic_output_shape_ops
    ):
        # Without symints/symfloats, cannot handle this
        raise DynamicOutputShapeException(func)

    if (nnz := arg.nonzero_memo) is None:
        # Avoid importing sympy at a module level
        from torch.fx.experimental.symbolic_shapes import (
            _constrain_range_for_size,
            has_free_symbols,
        )
        from torch.utils._sympy.numbers import IntInfinity
        from torch.utils._sympy.value_ranges import bound_sympy

        if not has_free_symbols(arg.numel()) and arg.numel() == 0:
            # If numel is zero, then the output size must be zero.
            # In this case, we must not allocate an unbacked SymInt,
            # because if we do, it will immediately get refined to
            # zero, but this will be inconsistent with size oblivious
            # tests (which will continue to claim that the unbacked
            # symint cannot equal zero).  We could also unconditionally
            # allocate an unbacked SymInt and not refine its range,
            # but this seems more precise.
            nnz = 0
        else:
            nnz = fake_mode.shape_env.create_unbacked_symint()

            maxval = sys.maxsize - 1

            if not has_free_symbols(arg.numel()):
                maxval = int(arg.numel())
            else:
                prod_node = math.prod(arg.shape).node  # type: ignore[union-attr]
                prod_range = bound_sympy(
                    prod_node.expr, prod_node.shape_env.var_to_range
                )
                if isinstance(prod_range.upper, IntInfinity):
                    maxval = sys.maxsize - 1
                else:
                    maxval = prod_range.upper

            _constrain_range_for_size(nnz, max=maxval)

        arg.nonzero_memo = nnz  # pyrefly: ignore[bad-assignment]
    return arg.new_empty_strided((nnz, arg.dim()), (1, nnz), dtype=torch.int64)  # type: ignore[return]

def run_and_get_code(
    fn: Callable[P, _T],
    *args: P.args,
    **kwargs: P.kwargs,
) -> tuple[_T, list[str]]:
    from .graph import GraphLowering

    source_codes: OrderedSet[str] = OrderedSet()

    def save_output_code(code: str) -> None:
        source_codes.add(code)

    with mock.patch.object(GraphLowering, "save_output_code", save_output_code):
        torch._dynamo.reset()
        result = fn(*args, **kwargs)
    return result, list(source_codes)

def _wrapper_cuda(fn):
    @wraps(fn)
    def decorated(*args, **kwargs):
        replace_int = fn.__name__ in ['to', 'to_empty']
        if args:
            args_new = list(args)
            args = _replace_cuda_to_npu_in_list(args_new, replace_int)
        if kwargs:
            for device_arg in device_kwargs_list:
                device = kwargs.get(device_arg, None)
                if device is not None:
                    _replace_cuda_to_npu_in_kwargs(kwargs, device_arg, device)
            device_ids = kwargs.get('device_ids', None)
            if isinstance(device_ids, list):
                kwargs["device_ids"] = _replace_cuda_to_npu_in_list(device_ids, replace_int)
            elif isinstance(device_ids, tuple):
                kwargs["device_ids"] = tuple(_replace_cuda_to_npu_in_list(list(device_ids), replace_int))
        return fn(*args, **kwargs)

    return decorated

def _device_wrapper(enter_fn, white_list):
    for fn_name in white_list:
        fn = getattr(enter_fn, fn_name, None)
        if fn:
            setattr(enter_fn, fn_name, _wrapper_cuda(fn))

def should_use_persistent_reduction(self) -> bool:
    """
    Heuristic to decide if a persistent reduction should be used.
    """
    if not self.inside_reduction:
        return False
    if not config.triton.persistent_reductions:
        return False
    reduction_node = self.find_reduction_node()
    reduction_numel = self.features.reduction_numel
    if isinstance(reduction_numel, NumelList):
        reduction_numel = reduction_numel.numels()
    if (
        npu_config.is_ascend950
        and npu_config.enable_welford
        and getattr(reduction_node, "reduction_type", None) == "welford_reduce"
        and V.graph.sizevars.statically_known_leq(reduction_numel, 8192)
    ):
        # A5 Welford SIMD consumes a static reduction tile. Its compiler
        # UB checks still reject individual oversized tile configurations.
        return True
    if npu_config.is_ascend950:
        threshold = {ReductionHint.INNER: 4096, ReductionHint.DEFAULT: 4096}.get(
            self.features.get_reduction_hint(), 64
        )
    else:
        threshold = {ReductionHint.INNER: 1024, ReductionHint.DEFAULT: 1024}.get(
            self.features.get_reduction_hint(), 64
        )
    if self.cooperative_reduction:
        # The RSPLIT of cooperative reductions means each thread block is operating on fewer elements
        try:
            threshold *= 32 // min(
                V.graph.sizevars.optimization_hint(self.features.numel), 32
            )
        except ValueError:
            pass  # unbacked symint

    if config.triton.multi_kernel:
        threshold *= 16
    return V.graph.sizevars.statically_known_leq(
        self.features.reduction_numel, threshold
    )  # type: ignore[arg-types]

def pow(arg0, arg1, _semantic=None):
    """
    Power function, computes x raised to the power of y.

    :param arg0: ``x``. Supported dtype(s): ``float32``.
    :type arg0: scalar or tl.tensor
    :param arg1: ``y``. Supported dtype(s): ``float32``.
    :type arg1: scalar or tl.tensor
    :return: x raised to the power of y.
    :rtype: ``float32``
    """
    arg0 = _semantic.to_tensor(arg0)
    arg1 = _semantic.to_tensor(arg1)
    if arg1.dtype == core.dtype("int32"):
        arg1 = _semantic.cast(arg1, arg0.dtype)

    if arg0.dtype == core.dtype("fp32") and _is_a5_target(_semantic):
        return core.extern_elementwise(
            "", "", [arg0, arg1], {
                (core.dtype("fp32"), core.dtype("fp32")): ("__hmf_pow_fp32", core.dtype("fp32")),
                (core.dtype("fp32"), core.dtype("int32")): ("__hmf_powi_fp32", core.dtype("fp32")),
            }, is_pure=True, _semantic=_semantic)
    return core.extern_elementwise(
        "", "", [arg0, arg1], {
            (core.dtype("fp32"), core.dtype("fp32")): ("__hmf_powf", core.dtype("fp32")),
            (core.dtype("fp16"), core.dtype("fp16")): ("__hmf_powDh", core.dtype("fp16")),
            (core.dtype("bf16"), core.dtype("bf16")): ("__hmf_powDb", core.dtype("bf16")),
        }, is_pure=True, _semantic=_semantic)

void npu_cpu_fallback(const c10::OperatorHandle& op, torch::jit::Stack* stack) {
  const auto op_name = c10::toString(op.schema().operator_name());
  at_npu::native::CheckCpuFallbackAllowed(
      op_name, at_npu::native::CpuFallbackKind::Dispatcher, "no kernel is registered for the NPU PrivateUse1 backend");

  if (!has_op_name_warned(op_name)) {
    TORCH_NPU_WARN(
        "CAUTION: The operator '",
        op.schema().operator_name(),
        "' is not currently supported ",
        "on the NPU backend and will fall back to run on the CPU.",
        " This may have performance implications.");
  }
  at::native::cpu_fallback(op, stack);
}

TORCH_LIBRARY_IMPL(_, PrivateUse1, m) {
  m.fallback(torch::CppFunction::makeFromBoxedFunction<&npu_cpu_fallback>());
}

at::Tensor& nonzero_out(const at::Tensor& self, at::Tensor& result)
{
    DO_COMPATIBILITY(aclnnNonzero, acl_op::nonzero_out(self, result));
    auto out_size = op_infer::nonzero_npu_max_output_size(self);
    at_npu::native::OpPreparation::check_tensor({self}, result, at::ScalarType::Long, out_size);
    auto out = result.is_contiguous() ? result : result.contiguous();
    auto output = exec_aclnn_non_zero(self, out);
    if (!result.is_contiguous()) {
        result.copy_(output);
    }
    return result;
}

at::Tensor nonzero(const at::Tensor& self)
{
    DO_COMPATIBILITY(aclnnNonzero, acl_op::nonzero(self));
    auto out_size = op_infer::nonzero_npu_max_output_size(self);
    at::Tensor out =
        at_npu::native::OpPreparation::apply_tensor_without_format(out_size, self.options().dtype(at::kLong));
    return exec_aclnn_non_zero(self, out);
}
